const {chromium} = require('C:/Users/User/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({channel:'msedge',headless:true});
 const page=await browser.newPage({viewport:{width:1280,height:900}});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:8765');
 await page.waitForFunction(()=>document.querySelector('#destination').textContent.includes('downloads'));
 if(await page.locator('#mode').inputValue()!=='mp3')throw Error('Default must remain MP3');
 await page.selectOption('#mode','both');
 await page.fill('#url','https://example.com/video');
 await page.click('#start');
 await page.waitForFunction(()=>document.querySelector('#error').textContent.includes('HTTPS YouTube'));
 await page.setInputFiles('#excel-file','outputs/party_20261008/Model_playlist_masa_si_petrecere.xlsx');
 await page.click('#excel-preview');
 await page.waitForFunction(()=>document.querySelector('#excel-count').textContent.includes('0 linkuri valide'));
 if(!await page.locator('#excel-start').isDisabled())throw Error('Empty model must not start');
 await page.setInputFiles('#excel-file','.runtime/import-test.xlsx');
 await page.click('#excel-preview');
 await page.waitForFunction(()=>document.querySelector('#excel-count').textContent.includes('4 linkuri valide'));
 if(await page.locator('#excel-links tr').count()!==4)throw Error('Preview row count');
 if(await page.locator('#excel-start').isDisabled())throw Error('Valid preview must enable start');
 let submittedMode;
 await page.route('**/api/imports/*/start',r=>{submittedMode=r.request().postDataJSON().mode;return r.fulfill({json:{id:'browser-test'},status:202})});
 await page.route('**/api/jobs/browser-test',r=>r.fulfill({json:{status:'done',message:'Import terminat',current:1,total:1,percent:100,files:[{artist:'Artist',title:'Video',format:'mp4',file:'Video.mp4'},{artist:'Artist',title:'Video',format:'mp3',file:'Video.mp3'}],errors:[],warnings:[],batch_current:4,batch_total:4,source_label:'Românești'}}));
 await page.click('#excel-start');
 await page.waitForFunction(()=>document.querySelector('#message').textContent==='Import terminat');
 if(submittedMode!=='both')throw Error('Excel mode not submitted');
 if(await page.locator('#results a').allTextContents().then(x=>x.join(','))!=='MP4 ↓,MP3 ↓')throw Error('Wrong file labels');
 await page.route('**/api/jobs',r=>{submittedMode=r.request().postDataJSON().mode;return r.fulfill({json:{id:'browser-test'},status:202})});
 await page.selectOption('#mode','mp4');
 await page.fill('#url','https://youtu.be/abcdefghijk');
 await page.click('#start');
 await page.waitForTimeout(200);
 if(submittedMode!=='mp4')throw Error('Single link mode not submitted');
 await page.screenshot({path:'.runtime/desktop.png',fullPage:true});
 await page.setViewportSize({width:390,height:844});
 if(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth))throw Error('Mobile overflow');
 await page.screenshot({path:'.runtime/mobile.png',fullPage:true});
 await browser.close();
 if(errors.length)throw Error(errors.join('\n'));
 console.log('Browser OK: page, invalid link, real empty model, Excel preview, mocked batch start, mobile layout, no JavaScript errors');
})().catch(e=>{console.error(e);process.exit(1)});
